files.rules/ingest-federation-source-stalled.y:
# I-4 · federation polling stopped without an error: the adapter task died (I-4.d),
# the adapters never registered (I-4.c) or the runner reads the source as off
# (I-4.e). No new success, no new failure. Gated on the global federation switch
# (global.enabled): with it off the legacy poller owns the source and
# last_success_at stalls by design.
apiVersion: medic.rules/v1
kind: Rule
id: ingest.federation-source-stalled
title: Federation source has stopped being polled
revision: 1
fault: {class: ingest, mode: I-4, causes: [I-4.c, I-4.d, I-4.e]}
lane: 3
detection: absence
signals:
  federation:   {sample: {signal: federation_sources, key: global.enabled}}
  enabled:      {sample: {signal: federation_sources, key: sources.enabled, by: [source]}}
  errors:       {sample: {signal: federation_sources, key: sources.consecutive_errors, by: [source]}}
  last_success: {sample: {signal: federation_sources, key: sources.last_success_at, by: [source]}}
group_by: [source]
when:
  all:
    - {fn: latest, signal: federation, op: "==", value: true}
    - {fn: latest, signal: enabled, op: "==", value: true}
    - {fn: latest, signal: errors, op: "==", value: 0}
    - any:
        - {fn: age, signal: last_success, op: ">", value: {param: stall_after}}
        - {fn: absent_for, signal: last_success, window: {param: never_polled_for}}
for: 10m
keep_firing_for: 10m
params:
  stall_after: {type: number, default: 3600, min: 900, max: 86400}
  never_polled_for: {type: duration, default: 1h, min: 15m, max: 24h}
advice:
  summary: This enabled source has had neither a successful nor a failed poll for an hour, so Vigil has stopped polling it.
  fix: >-
    Restart soc-daemon; polling should resume within one interval. If it stops
    again, or never starts, report it as a Vigil defect with this incident and
    the soc-daemon log from its start-up.

files.rules/llm-default-provider-keyless.yaml:
# L-1.a (from E2's fixture llm-provider-keyless-default). Ollama and Vertex rows carry
# no API key by design (core/llm/bifrost/admin.py:69-76: Ollama's key is a URL, Vertex's a
# service-account file), so the provider type guard keeps this quiet on those installs
# (has_api_key = api_key_ref is set, core/storage/schemas/ai.py:87).
apiVersion: medic.rules/v1
kind: Rule
id: llm.default-provider-keyless
title: Default LLM provider has no API key
revision: 1
fault: {class: llm, mode: L-1, causes: [L-1.a]}
lane: 2
detection: event
signals:
  is_default: {sample: {signal: llm_providers, key: providers.is_default, by: [provider]}}
  is_active: {sample: {signal: llm_providers, key: providers.is_active, by: [provider]}}
  has_key: {sample: {signal: llm_providers, key: providers.has_api_key, by: [provider]}}
  kind: {sample: {signal: llm_providers, key: providers.provider_type, by: [provider]}}
group_by: [provider]
when:
  all:
    - {fn: latest, signal: is_default, op: "==", value: true}
    - {fn: latest, signal: is_active, op: "==", value: true}
    - {fn: latest, signal: has_key, op: "==", value: false}
    - {fn: latest, signal: kind, op: "!=", value: ollama}
    - {fn: latest, signal: kind, op: "!=", value: vertex}
for: 5m
keep_firing_for: 5m
advice:
  summary: The default LLM provider is active but has no API key, so chat and triage calls will fail.
  fix: >-
    Open Settings, LLM providers. Add an API key to the default provider, or make
    a provider that has a key the default.

files.rules/pipeline-daemon-component-failed.y:
# P-3.a / P-3.b · a top-level soc-daemon task died (crashed or stopped), e.g. the
# scheduler raising at start-up. /health says 503 then, but an unconfigured
# optional component ("not_initialized") does too, so the rule reads the
# per-component state (daemon_health components.<name>, "failed: <Exc>" folded to
# "failed"), not the overall status.
apiVersion: medic.rules/v1
kind: Rule
id: pipeline.daemon-component-failed
title: A soc-daemon component has stopped
revision: 1
fault: {class: pipeline, mode: P-3, causes: [P-3.a, P-3.b]}
lane: 3
detection: event
signals:
  processor:    {sample: {signal: daemon_health, key: components.processor}}
  scheduler:    {sample: {signal: daemon_health, key: components.scheduler}}
  orchestrator: {sample: {signal: daemon_health, key: components.orchestrator}}
  poller:       {sample: {signal: daemon_health, key: components.poller}}
when:
  any:
    - {fn: latest, signal: processor, op: "==", value: failed}
    - {fn: latest, signal: processor, op: "==", value: stopped}
    - {fn: latest, signal: scheduler, op: "==", value: failed}
    - {fn: latest, signal: scheduler, op: "==", value: stopped}
    - {fn: latest, signal: orchestrator, op: "==", value: failed}
    - {fn: latest, signal: orchestrator, op: "==", value: stopped}
    - {fn: latest, signal: poller, op: "==", value: failed}
    - {fn: latest, signal: poller, op: "==", value: stopped}
for: 2m
keep_firing_for: 5m
advice:
  summary: A soc-daemon component (processor, scheduler, orchestrator or poller) has stopped while the daemon keeps running.
  fix: >-
    Report it as a Vigil defect with this incident. Restart soc-daemon; the
    component starts again with it. Attach the soc-daemon log from before the
    restart (it names the component and the error), and record that you
    restarted it.

files.rules/pipeline-daemon-component-hung.yam:
# P-3.a / P-3.b · a soc-daemon component reads "running" but does no work: the
# processor processes nothing while webhook findings arrive, or the scheduler
# runs no task for 20 min although health_check runs every 300 s
# (scheduler.py:117-124). A database outage stalls processing too:
# suppression.yaml makes this a child of the ingest database rules.
apiVersion: medic.rules/v1
kind: Rule
id: pipeline.daemon-component-hung
title: A soc-daemon component reports running but does no work
revision: 1
fault: {class: pipeline, mode: P-3, causes: [P-3.a, P-3.b]}
lane: 3
detection: absence
signals:
  processor: {sample: {signal: daemon_health, key: components.processor}}
  scheduler: {sample: {signal: daemon_health, key: components.scheduler}}
  uptime:    {sample: {signal: daemon_health, key: uptime_seconds}}
  processed: {sample: {signal: daemon_status.processor, key: processed}}
  arrivals:  {sample: {signal: daemon_status.poller, key: webhook_findings}}
  tasks_run: {sample: {signal: daemon_status.scheduler, key: tasks_run}}
when:
  all:
    - {fn: latest, signal: uptime, op: ">", value: 1200}
    - any:
        - all:
            - {fn: latest, signal: processor, op: "==", value: running}
            - {fn: changes, signal: processed, window: 15m, op: "==", value: 0}
            - {fn: increase, signal: arrivals, window: 15m, op: ">", value: 0}
        - all:
            - {fn: latest, signal: scheduler, op: "==", value: running}
            - {fn: changes, signal: tasks_run, window: 20m, op: "==", value: 0}
for: 5m
keep_firing_for: 10m
advice:
  summary: A soc-daemon component (processor or scheduler) reports running but has done no work for 15 to 20 minutes.
  fix: >-
    Report it as a Vigil defect with this incident. Restarting soc-daemon
    usually restores the component; attach the soc-daemon log from before the
    restart and record that you restarted it.

files.rules/pipeline-orchestrator-slots-held.y:
# P-2.c · every orchestrator slot is held (parked runs waiting for an answer can
# hold one for up to 7 days, by design: #1550) while intake work queues. The
# orchestrator logs nothing when it is at capacity, and the rule language can't
# compare two signals, so the rule reads free_slots (max_concurrent_agents minus
# in-flight runs, waiting approvals included) from the daemon's /status.
apiVersion: medic.rules/v1
kind: Rule
id: pipeline.orchestrator-slots-held
title: New investigations are waiting while every run slot is held
revision: 1
fault: {class: pipeline, mode: P-2, causes: [P-2.c]}
lane: 2
detection: absence
signals:
  enabled:   {sample: {signal: orchestrator_status, key: enabled}}
  queued:    {sample: {signal: orchestrator_status, key: queued}}
  free:      {sample: {signal: daemon_status.orchestrator, key: free_slots}}
  created:   {sample: {signal: daemon_status.orchestrator, key: investigations_created}}
  completed: {sample: {signal: daemon_status.orchestrator, key: investigations_completed}}
when:
  all:
    - {fn: latest, signal: enabled, op: "==", value: true}
    - {fn: latest, signal: queued, op: ">", value: 0}
    - {fn: latest, signal: free, op: "<=", value: 0}
    - {fn: increase, signal: created, window: {param: stalled_for}, op: "==", value: 0}
    - {fn: increase, signal: completed, window: {param: stalled_for}, op: "==", value: 0}
for: 15m
keep_firing_for: 15m
params:
  stalled_for: {type: duration, default: 2h, min: 30m, max: 24h}
advice:
  summary: Work is queued for investigation, but every run slot has been held for 2 hours and nothing new has started or finished.
  fix: >-
    Open the investigations waiting for an answer or approval in the console and
    answer or cancel them to free their slots. If nothing is waiting on you,
    raise the maximum concurrent agents in the orchestrator settings. If that
    does not help, report it as a Vigil defect with this incident.

files.suppression.yaml:
# Dependency suppression (E3 §6). Entries are grouped by the class that owns the
# child; keep each batch's entries under its heading when merging.
apiVersion: medic.suppression/v1
kind: Suppression
entries:
  # --- ingest (F7a) ---
  - parent: {rule: ingest.processor-without-database}
    children: {rule: ingest.source-polls-failing}
    why: With no database every finding is dropped and federation records each tick as a failure. Show the database fault, not a credential fault per source.
  - parent: {rule: ingest.processor-without-database}
    children: {rule: ingest.processor-store-dropped}
    why: Each dropped finding is a symptom of the processor having no database.
  - parent: {rule: ingest.federation-integration-disabled}
    children: {rule: ingest.federation-source-stalled}
    match: [source]
    why: A source whose integration is off is skipped, so its last success stalls with no error. Show the configuration fault.
  # --- llm (F7b) ---
  # The pipeline children these point at ship with the pipeline batches.
  - parent: {class: llm}
    children: {mode: P-4}
    why: Triage stalls whenever the LLM path is down (B5 P-4.a). Show the LLM fault, not the stall.
  - parent: {mode: L-5}
    children: {cause: P-2.e}
    why: A spent budget abandons runs (B5 P-2.e).
  - parent: {mode: L-3}
    children: {cause: P-2.e}
    why: LLM jobs with no consumer stall runs (B5 P-2.e).
  - parent: {rule: llm.provider-key-unusable}
    children: {rule: llm.calls-failing}
    why: Rejected-key errors are LLM call failures too. Show the key, not the generic failure count.
  - parent: {rule: llm.model-unservable}
    children: {rule: llm.calls-failing}
    why: Unservable-model errors are LLM call failures too. Show the model, not the generic failure count.
  - parent: {rule: llm.rate-limited}
    children: {rule: llm.calls-failing}
    why: Rate-limit errors are LLM call failures too. Show the quota, not the generic failure count.
  - parent: {rule: llm.gateway-unreachable}
    children: {rule: llm.calls-failing}
    why: With Bifrost unreachable every call fails. Show the gateway, not the generic failure count.
  # --- pipeline (F7c) ---
  # processor-errors and triage-stalled (mode P-4) are already children of class llm above.
  - parent: {mode: L-5}
    children: {rule: pipeline.orchestrator-slots-held}
    why: A spend cap or exhausted budget holds new runs too; show the budget fault.
  - parent: {rule: ingest.processor-without-database}
    children: {rule: pipeline.daemon-component-hung}
    why: With no database nothing is processed while findings still arrive; show the database fault, not a hung processor.
  - parent: {rule: ingest.processor-store-dropped}
    children: {rule: pipeline.daemon-component-hung}
    why: Findings that fail to store aren't processed; show the store fault, not a hung processor.
  # --- pipeline: agent and run queue (F7c-agents) ---
  - parent: {rule: pipeline.agent-serve-not-ready}
    children: {rule: pipeline.agent-reads-failing}
    why: When agent-serve reports not ready, the backend's reads of it fail too. Show the service fault, not the failed reads.
